// ILANG
// TYPE:worker ROLE:canonical-host-and-real-404
// ::RULE{non-canonical hosts get a 301 to the canonical domain; never leave two live addresses}
// ::RULE{paths outside the allow-list get a real 404; never let Pages fall back to the homepage}
// ::RULE{the allow-list is generated by build.py, so adding a page needs no edit here}
// ::BOUNDARY{never:render content from this file|scope:file}
const CANONICAL_HOST = "vpsdealsradar.com";
const VALID_PATHS = new Set(["/", "/compare", "/about", "/methodology", "/privacy", "/contact", "/sitemap.xml", "/robots.txt", "/guide", "/assets/favicon.svg", "/assets/pets.js", "/assets/style.css", "/og.png", "/assets/per-gb-cheapest.svg", "/assets/per-gb-hostwinds.svg", "/assets/monthly-vs-ram-hostwinds.svg", "/assets/per-gb-ionos.svg", "/assets/monthly-vs-ram-ionos.svg", "/assets/per-gb-ovhcloud.svg", "/assets/monthly-vs-ram-ovhcloud.svg", "/assets/per-gb-netcup.svg", "/assets/monthly-vs-ram-netcup.svg", "/downloads/unit-price.csv", "/provider/ovhcloud", "/provider/netcup", "/provider/digitalocean", "/provider/buyvm", "/provider/ionos", "/provider/hostwinds", "/provider/hetzner", "/deal/ovhcloud-vps-1", "/deal/ovhcloud-vps-2", "/deal/ovhcloud-vps-3", "/deal/ovhcloud-vps-4", "/deal/netcup-vps-500-g12-5", "/deal/netcup-vps-1000-g12-5", "/deal/netcup-vps-2000-g12-5", "/deal/netcup-vps-4000-g12-5", "/deal/netcup-vps-8000-g12-5", "/deal/buyvm-high-volume-vps", "/deal/ionos-vps-s", "/deal/ionos-vps-m", "/deal/ionos-vps-l", "/deal/ionos-vps-xl", "/deal/ionos-vps-xxl", "/deal/hostwinds-unmanaged-linux-vps-hosting-1-cpu-1-gb-ram-30-gb", "/deal/hostwinds-unmanaged-linux-vps-hosting-1-cpu-2-gb-ram-50-gb", "/deal/hostwinds-unmanaged-linux-vps-hosting-2-cpu-4-gb-ram-75-gb", "/deal/hostwinds-unmanaged-linux-vps-hosting-2-cpu-6-gb-ram-100-gb", "/deal/hostwinds-unmanaged-linux-vps-hosting-4-cpu-8-gb-ram-150-gb", "/deal/hostwinds-unmanaged-linux-vps-hosting-4-cpu-12-gb-ram-200-gb", "/deal/hostwinds-unmanaged-linux-vps-hosting-6-cpu-16-gb-ram-300-gb", "/deal/hostwinds-unmanaged-linux-vps-hosting-8-cpu-32-gb-ram-400-gb", "/deal/hostwinds-unmanaged-linux-vps-hosting-12-cpu-64-gb-ram-500-gb", "/deal/hostwinds-unmanaged-linux-vps-hosting-16-cpu-96-gb-ram-750-gb", "/guide/vps-comparison-table-csv", "/guide/how-to-buy-and-connect-a-cheap-vps", "/guide/how-vps-pricing-works", "/guide/csv-2026-09-21-1", "/guide/unitprice-2026-09-22-1", "/guide/steps-2026-09-23-1", "/guide/csv-2026-09-24-1", "/guide/unitprice-2026-09-25-1", "/guide/steps-2026-09-26-1", "/guide/csv-2026-09-27-1", "/guide/unitprice-2026-09-28-1", "/guide/steps-2026-09-29-1", "/guide/csv-2026-09-30-1", "/guide/unitprice-2026-10-01-1"]);

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.hostname !== CANONICAL_HOST) {
      return Response.redirect(new URL(url.pathname + url.search, `https://${CANONICAL_HOST}`).toString(), 301);
    }

    const path = url.pathname.replace(/\/+$/, "") || "/";

    // Legacy /xxx.html addresses from earlier deploys: permanent redirect to the clean path
    if (path.endsWith(".html")) {
      const bare = path === "/index.html" ? "/" : path.slice(0, -5);
      if (VALID_PATHS.has(bare)) {
        return Response.redirect(new URL(bare + url.search, `https://${CANONICAL_HOST}`).toString(), 308);
      }
    }

    if (VALID_PATHS.has(path)) {
      return env.ASSETS.fetch(request);
    }

    // Cloudflare Pages answers unmatched paths with the homepage and a 200.
    // Turn that into a real 404: search engines and reviewers should not see a valid page
    // at an address that does not exist.
    const notFound = await env.ASSETS.fetch(new URL("/404.html", url));
    return new Response(notFound.body, {
      status: 404,
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store",
        "x-robots-tag": "noindex",
      },
    });
  },
};
